139	  public <L, W> HoodiePairData<L, W> mapToPair(SerializablePairFunction<Pair<K, V>, L, W> mapToPairFunc) {
140	    return HoodieJavaPairRDD.of(pairRDDData.mapToPair(pair -> {
141	      Pair<L, W> newPair = mapToPairFunc.call(new ImmutablePair<>(pair._1, pair._2));
142	      return new Tuple2<>(newPair.getLeft(), newPair.getRight());
143	    }));
144	  }
