148	    return HoodieJavaPairRDD.of(JavaPairRDD.fromJavaRDD(
149	        pairRDDData.leftOuterJoin(HoodieJavaPairRDD.getJavaPairRDD(other))
150	            .map(tuple -> new Tuple2<>(tuple._1,
151	                new ImmutablePair<>(tuple._2._1, Option.ofNullable(tuple._2._2.orElse(null)))))));
152	  }
