164	  @Override
165	  public <W> HoodiePairData<K, Pair<V, W>> join(HoodiePairData<K, W> other) {
166	    return HoodieJavaPairRDD.of(JavaPairRDD.fromJavaRDD(
167	        pairRDDData.join(HoodieJavaPairRDD.getJavaPairRDD(other))
168	            .map(tuple -> new Tuple2<>(tuple._1,
169	                new ImmutablePair<>(tuple._2._1, tuple._2._2)))));
170	  }
171	
172	  @Override
173	  public List<Pair<K, V>> collectAsList() {
174	    return pairRDDData.map(t -> Pair.of(t._1, t._2)).collect();
175	  }
176	
177	  @Override
178	  public int deduceNumPartitions() {
179	    // for source rdd, the partitioner is None
180	    final Optional<Partitioner> partitioner = pairRDDData.partitioner();
181	    if (partitioner.isPresent()) {
182	      int partPartitions = partitioner.get().numPartitions();
183	      if (partPartitions > 0) {
184	        return partPartitions;
185	      }
186	    }
187	
188	    if (SQLConf.get().contains(SQLConf.SHUFFLE_PARTITIONS().key())) {
189	      return Integer.parseInt(SQLConf.get().getConfString(SQLConf.SHUFFLE_PARTITIONS().key()));
190	    } else if (pairRDDData.context().conf().contains("spark.default.parallelism")) {
191	      return pairRDDData.context().defaultParallelism();
192	    } else {
193	      return pairRDDData.getNumPartitions();
194	    }
195	  }
