 * {@link HoodiePairData} collections. When an operation fails partway through, these intermediate
 * collections may retain memory (for example, cached Spark RDDs) that would otherwise leak because
 * the caller never receives a handle to unpersist them. This manager keeps track of such
 * collections and, on exception, recursively un-persists them (along with their upstream
 * dependencies) before re-throwing.
 *
 * <p>Tracking is isolated per-thread using the thread id, so concurrent callers do not interfere
 * with each other's tracked data.
 */
public class HoodieDataCleanupManager {

  private static final Logger LOG = LoggerFactory.getLogger(HoodieDataCleanupManager.class);

  private final ConcurrentHashMap<Long, List<Object>> threadPersistedData = new ConcurrentHashMap<>();

  public HoodieDataCleanupManager() {
  }

  /**
   * Tracks a {@link HoodiePairData} collection for the current thread so that it can be released
   * if the enclosing operation fails.
   *
   * @param data the collection to track
   */
  public void trackPersistedData(HoodiePairData<?, ?> data) {
    addToTrackedData(data);
  }

  /**
   * Tracks a {@link HoodieData} collection for the current thread so that it can be released
   * if the enclosing operation fails.
   *
   * @param data the collection to track
   */
  public void trackPersistedData(HoodieData<?> data) {
    addToTrackedData(data);
  }

  private void addToTrackedData(Object data) {
    long threadId = Thread.currentThread().getId();
    threadPersistedData.computeIfAbsent(threadId, k -> new java.util.ArrayList<>()).add(data);
  }

