   * throws, all data collections tracked for the current thread are released (via
   * {@code unpersistWithDependencies()}), the tracking list for the current thread is cleared, and
   * the original exception is re-thrown unchanged.
   *
   * @param operation the operation to execute
   * @param <T>       result type of the operation
   * @return the result of the operation
   */
  public <T> T ensureDataCleanupOnException(SerializableFunctionUnchecked<Void, T> operation) {
    try {
      return operation.apply(null);
    } catch (Throwable t) {
      cleanupPersistedData();
      throw t;
    }
  }

  /**
   * Releases all data collections tracked for the current thread and clears the tracking list.
   *
   * <p>Cleanup continues for the remaining tracked objects even if un-persisting one of them
   * throws. Null entries and objects that are neither {@link HoodieData} nor {@link HoodiePairData}
   * are silently skipped.
   */
  private void cleanupPersistedData() {
    long threadId = Thread.currentThread().getId();
    List<Object> persistedData = threadPersistedData.remove(threadId);
    if (persistedData == null) {
      return;
    }
    for (Object data : persistedData) {
      try {
